package org.sleepwell.app;
import java.util.*;import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
/** Real production pump/DSP over deterministic acoustic paths; no Android audio APIs. */
public class SonarPumpTest {
 static final class Clock implements SonarPump.Clock {long time;public long millis(){return time;}public void idle()throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();time+=10;}}
 static class Io implements SonarPump.Io {
  long written,read,origin=-1;int gains,closes;boolean route=true,readStall,writeStall,closed;int maxWrite=480,maxRead=480;double drift;SonarFrame.Quality failure;AtomicBoolean cancelled;boolean loseBeforeGain;int failAt=Integer.MAX_VALUE;boolean rampObserved;
  public void startMuted(){}public void check()throws Exception{if(failure!=null&&read>=failAt)throw new SonarPump.Failure(failure,"Injected "+failure);}
  public boolean routed(){return route;}public void confirmRoutes(){if(loseBeforeGain)route=false;}
  public SonarPump.Timing timing(){return new SonarPump.Timing(read>20000?drift:0);}
  public void gain(float g)throws Exception{assertTrue(g<=.10f&&g>=.01f);if(!route)throw new SonarPump.Failure(SonarFrame.Quality.ROUTE_LOST,"Route lost before emission");gains++;origin=written;}
  public int write(short[] data,int at,int count){if(writeStall)return 0;int n=Math.min(maxWrite,count);if(origin>=0&&written==origin){assertEquals(0,data[at]);rampObserved=true;}written+=n;return n;}
  public int read(short[] data,int at,int count){if(readStall)return 0;int n=(int)Math.min(Math.min(maxRead,count),written-read);for(int k=0;k<n;k++){long t=read+k-origin;double frame=t/1920d,delay=frame>=60&&frame<100?240+5*Math.sin(Math.floor(frame)*.3):240;double v=origin<0?0:.5*SonarChirp.sample(t-8)+.16*SonarChirp.sample(t-delay);data[at+k]=(short)Math.round(v*32767);}read+=n;return n;}
  public void close(){closed=true;closes++;}
 }
 @Test public void partialDuplexProducesMeasuredEchoThenZeroAndCloses()throws Exception{Io io=new Io();io.maxWrite=137;io.maxRead=113;List<SonarFrame> frames=new ArrayList<>();SonarFrame last=SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),new Clock(),frames::add);assertEquals(1,io.gains);assertTrue(io.rampObserved);assertEquals(1,io.closes);assertTrue(frames.stream().anyMatch(f->f.movement!=null&&f.movement>.03));assertNotNull(last.movement);assertEquals(0,last.movement,1e-5);assertTrue(frames.size()<=500);}
 @Test public void unconfirmedOrLostRouteNeverEmits()throws Exception{for(boolean lost:new boolean[]{false,true}){Io io=new Io();io.route=lost;io.loseBeforeGain=lost;assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),new Clock(),f->fail("No emitted sample")));assertEquals(0,io.gains);assertTrue(io.closed);}}
 @Test public void progressingSpeakerCannotHideStalledMicrophone()throws Exception{Io io=new Io();io.readStall=true;Clock clock=new Clock();assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),clock,f->fail()));assertTrue(clock.time<=610);assertTrue(io.closed);}
 @Test public void progressingMicrophoneCannotHideStalledSpeaker()throws Exception{Io io=new Io();io.writeStall=true;Clock clock=new Clock();assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),clock,f->fail()));assertTrue(clock.time<=610);assertTrue(io.closed);}
 @Test public void clockDiscontinuityCannotBecomeMotion()throws Exception{Io io=new Io();io.drift=8;SonarPump.Failure error=assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),new Clock(),f->{}));assertEquals(SonarFrame.Quality.TIMING_LOST,error.quality);assertTrue(io.closed);}
 @Test public void routeSilencingChargingFailuresAndCancelCloseWithoutReady()throws Exception{for(SonarFrame.Quality quality:new SonarFrame.Quality[]{SonarFrame.Quality.ROUTE_LOST,SonarFrame.Quality.SILENCED,SonarFrame.Quality.CHARGING_LOST}){Io io=new Io();io.failure=quality;io.failAt=40000;assertEquals(quality,assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),new Clock(),f->{})).quality);assertTrue(io.closed);}Io io=new Io();AtomicBoolean cancelled=new AtomicBoolean();SonarPump.run(io,SonarConfig.defaults(),cancelled,new Clock(),f->cancelled.set(true));assertTrue(cancelled.get());assertTrue(io.closed);}
 @Test public void cleanupFailureDoesNotMaskOriginalFailure(){Io io=new Io(){public void close(){super.close();throw new IllegalStateException("cleanup");}};io.readStall=true;Exception e=assertThrows(SonarPump.Failure.class,()->SonarPump.run(io,SonarConfig.defaults(),new AtomicBoolean(),new Clock(),f->{}));assertEquals(1,e.getSuppressed().length);assertEquals("cleanup",e.getSuppressed()[0].getMessage());}
}
